const { readFileSync, writeFileSync } = require('node:fs');
const path = require('node:path');
const root = path.join(__dirname, '..');
const read = (name) => readFileSync(path.join(root, name), 'utf8');
const assets = {
  leafletJs: read('node_modules/leaflet/dist/leaflet.js').replace(/\/\/# sourceMappingURL=.*$/m, ''),
  leafletCss: read('node_modules/leaflet/dist/leaflet.css'),
  mapRuntime: read('src/components/map/mapRuntime.js'),
  mapCss: read('src/components/map/map.css'),
};
const output = '// Generated by scripts/build-map-assets.cjs. Includes Leaflet 1.9.4 (BSD-2-Clause).\n'
  + Object.entries(assets).map(([name, value]) => `export const ${name} = ${JSON.stringify(value)};`).join('\n') + '\n';
writeFileSync(path.join(root, 'src/components/map/generatedAssets.ts'), output);
writeFileSync(path.join(root, 'src/components/map/LEAFLET-LICENSE.txt'), read('node_modules/leaflet/LICENSE'));
console.log('Bundled Leaflet, map runtime, and styles.');
